/**
 * cours-scripts-menu.mjs — KJEMO-UX-ACCUEIL-01 (alignement sur les formatifs du prof)
 * ---------------------------------------------------------------------------
 * Deux scripts Bash AU NIVEAU DU COURS, écrits sur le modèle des corrigés du
 * professeur (formatifs 1 et 2) : fonctions, while + read, if, case, un menu
 * `while [ "$rep" -eq 1 ]` + `case`. Rien de plus avancé : ni tableaux
 * associatifs, ni expressions régulières, ni getopts.
 *
 *  - SCRIPT_MENU_UTILISATEURS : le menu « vérifier un utilisateur / son UID / quitter ».
 *  - SCRIPT_MENU_COMPTES_SAMBA : le script du TP2, partie A (créer les comptes depuis le CSV,
 *    lister comptes, groupes et membres) sous forme de menu.
 *
 * Les deux sont affichés dans une fiche ET exécutés par test/cours-menu.test.mjs
 * (le second contre un FAUX samba-tool) : le texte affiché est le texte testé.
 *
 * Limites dites en clair : le mot de passe est passé en argument à samba-tool
 * (visible un instant dans la liste des processus : laboratoire isolé seulement) ;
 * le CSV doit avoir des fins de ligne Linux (créé avec nano sur la VM) ; pas de
 * guillemets dans le CSV.
 */
export const SCRIPT_MENU_UTILISATEURS_LIGNES = [
  "#!/bin/bash",
  "function pause {",
  "  echo \"Appuie sur Entrée pour continuer\"",
  "  read -r",
  "}",
  "function saisir_utilisateur {",
  "  echo \"Nom de l'utilisateur ?\"",
  "  read -r util",
  "}",
  "function verifier_utilisateur {",
  "  if grep \"^$util:\" /etc/passwd > /dev/null; then",
  "    echo \"L'utilisateur $util existe\"",
  "  else",
  "    echo \"L'utilisateur $util n'existe pas\"",
  "  fi",
  "  pause",
  "}",
  "rep=1",
  "while [ \"$rep\" -eq 1 ]; do",
  "  clear",
  "  printf \"Menu :\\n\\n\"",
  "  echo \"1. Vérifier l'existence d'un utilisateur\"",
  "  echo \"2. Connaître l'UID et les groupes d'un utilisateur\"",
  "  echo -e \"3. Quitter\\n\"",
  "  read -r choix",
  "  case \"$choix\" in",
  "    1)",
  "      saisir_utilisateur",
  "      verifier_utilisateur ;;",
  "    2)",
  "      saisir_utilisateur",
  "      id \"$util\"",
  "      pause ;;",
  "    3)",
  "      echo \"Au revoir\"",
  "      rep=0 ;;",
  "    *)",
  "      echo \"Choix invalide\"",
  "      pause ;;",
  "  esac",
  "done",
];

export const SCRIPT_MENU_COMPTES_SAMBA_LIGNES = [
  "#!/bin/bash",
  "function pause {",
  "  echo \"Appuie sur Entrée pour continuer\"",
  "  read -r",
  "}",
  "function creer_comptes {",
  "  echo \"Nom du fichier CSV (login;motdepasse;departement) ?\"",
  "  read -r csv",
  "  if [ ! -f \"$csv\" ]; then",
  "    echo \"Fichier introuvable : $csv\"",
  "    pause",
  "    return",
  "  fi",
  "  while IFS=';' read -r -u 3 login mdp dept || [ -n \"$login\" ]; do",
  "    dept=${dept%$'\\r'}",
  "    if [ -z \"$dept\" ]; then",
  "      echo \"Ligne ignorée : il faut 3 champs séparés par ;\"",
  "      continue",
  "    fi",
  "    if [ \"$login\" = \"login\" ]; then",
  "      continue",
  "    fi",
  "    case \"$mdp\" in",
  "      FICTIF-*)",
  "        echo \"$login : mot de passe du modèle, remplace-le dans ton CSV\"",
  "        continue ;;",
  "    esac",
  "    samba-tool group add \"$dept\" > /dev/null 2>&1 < /dev/null",
  "    if erreur=$(samba-tool user create \"$login\" \"$mdp\" 2>&1 < /dev/null); then",
  "      echo \"Compte créé : $login\"",
  "    else",
  "      echo \"ÉCHEC : $login\"",
  "      echo \"  ${erreur//\"$mdp\"/***}\" | head -n 2",
  "      continue",
  "    fi",
  "    if erreur=$(samba-tool group addmembers \"$dept\" \"$login\" 2>&1 < /dev/null); then",
  "      echo \"  ajouté au groupe $dept\"",
  "    else",
  "      echo \"  ÉCHEC : $login n'a pas pu être ajouté au groupe $dept\"",
  "      echo \"  $erreur\" | head -n 2",
  "    fi",
  "  done 3< \"$csv\"",
  "  pause",
  "}",
  "function lister_comptes {",
  "  samba-tool user list",
  "  pause",
  "}",
  "function lister_groupes {",
  "  samba-tool group list",
  "  pause",
  "}",
  "function lister_membres {",
  "  echo \"Nom du groupe (département) ?\"",
  "  read -r dept",
  "  samba-tool group listmembers \"$dept\"",
  "  pause",
  "}",
  "rep=1",
  "while [ \"$rep\" -eq 1 ]; do",
  "  clear",
  "  printf \"Menu - comptes Samba :\\n\\n\"",
  "  echo \"1. Créer les comptes depuis le fichier CSV\"",
  "  echo \"2. Lister les comptes\"",
  "  echo \"3. Lister les groupes\"",
  "  echo \"4. Lister les membres d'un groupe\"",
  "  echo -e \"5. Quitter\\n\"",
  "  read -r choix",
  "  case \"$choix\" in",
  "    1) creer_comptes ;;",
  "    2) lister_comptes ;;",
  "    3) lister_groupes ;;",
  "    4) lister_membres ;;",
  "    5)",
  "      echo \"Au revoir\"",
  "      rep=0 ;;",
  "    *)",
  "      echo \"Choix invalide\"",
  "      pause ;;",
  "  esac",
  "done",
];

export const SCRIPT_MENU_UTILISATEURS = SCRIPT_MENU_UTILISATEURS_LIGNES.join("\n") + "\n";
export const SCRIPT_MENU_COMPTES_SAMBA = SCRIPT_MENU_COMPTES_SAMBA_LIGNES.join("\n") + "\n";
